#!/usr/bin/env node
const fs = require('fs');
const path = require('path');

const archivos = {
  ".gitignore": "node_modules/\n.expo/\ndist/\nweb-build/\nandroid/\nios/\n*.apk\n*.aab\n*.keystore\n*.jks\n.env\n.env.*\nnpm-debug.*\n.DS_Store\n",
  "App.js": "import React from 'react';\nimport { StatusBar } from 'expo-status-bar';\nimport { SafeAreaProvider } from 'react-native-safe-area-context';\nimport { AuthProvider } from './context/AuthContext';\nimport { TasksProvider } from './context/TasksContext';\nimport AppNavigator from './navigation/AppNavigator';\nimport UpdateChecker from './components/UpdateChecker';\n\nexport default function App() {\n  return (\n    <SafeAreaProvider>\n      <AuthProvider>\n        <TasksProvider>\n          <StatusBar style=\"dark\" />\n          <AppNavigator />\n          <UpdateChecker />\n        </TasksProvider>\n      </AuthProvider>\n    </SafeAreaProvider>\n  );\n}\n",
  "README.md": "# TecSolv\n\nApp móvil de gestión académica (React Native + Expo). Registro e inicio de sesión, tareas con fecha límite, estado y prioridad, almacenamiento local.\n\n## Descargar e instalar (usuarios)\n\n1. Entra a la pestaña **Releases** de este repositorio.\n2. Descarga `TecSolv.apk` de la versión más reciente.\n3. Ábrelo en tu Android y permite instalar apps de origen desconocido si te lo pide.\n\nLa app avisa sola cuando hay una versión nueva al abrirla.\n\n## Orden para publicar (desarrollador)\n\n1. Crea un repositorio **público** vacío en GitHub (sin README).\n2. En una carpeta vacía: `node crear-proyecto.js` y luego `cd tecsolv`.\n3. `npm install`\n4. `npm run subir -- https://github.com/TU_USUARIO/tecsolv.git`\n5. En GitHub: **Settings → Actions → General → Workflow permissions → Read and write permissions**, y guarda.\n6. En **Actions**, ejecuta el workflow si no arrancó solo. Al terminar (10-20 min) aparece el APK en **Releases**.\n\n## Publicar actualizaciones\n\n```\nnpm run actualizar -- \"descripción del cambio\"\n```\n\nCada push a `main` compila un APK nuevo y crea un release. Quienes ya tienen la app reciben el aviso \"Actualización disponible\" al abrirla.\n\n## Desarrollo\n\n```\nnpm install\nnpx expo start\n```\n\n## Notas\n\n- El repositorio debe ser público para que la app consulte los releases.\n- Todas las compilaciones se firman igual, así que cada APK se instala encima de la versión anterior sin desinstalar.\n- Los datos se guardan en el dispositivo (AsyncStorage) y se conservan al actualizar.\n",
  "app.config.js": "module.exports = ({ config }) => {\n  const build = process.env.BUILD_NUMBER ? parseInt(process.env.BUILD_NUMBER, 10) : 0;\n  return {\n    ...config,\n    android: {\n      ...config.android,\n      versionCode: build > 0 ? build : (config.android && config.android.versionCode) || 1,\n    },\n    extra: {\n      ...(config.extra || {}),\n      buildNumber: build,\n      githubRepo: process.env.GITHUB_REPOSITORY || '',\n    },\n  };\n};\n",
  "app.json": "{\n  \"expo\": {\n    \"name\": \"TecSolv\",\n    \"slug\": \"tecsolv\",\n    \"version\": \"1.0.0\",\n    \"orientation\": \"portrait\",\n    \"userInterfaceStyle\": \"light\",\n    \"scheme\": \"tecsolv\",\n    \"assetBundlePatterns\": [\"**/*\"],\n    \"android\": {\n      \"package\": \"mx.edu.itcv.tecsolv\",\n      \"versionCode\": 1,\n      \"permissions\": [\n        \"POST_NOTIFICATIONS\",\n        \"SCHEDULE_EXACT_ALARM\",\n        \"RECEIVE_BOOT_COMPLETED\",\n        \"VIBRATE\"\n      ]\n    },\n    \"plugins\": [\n      [\n        \"expo-notifications\",\n        {\n          \"color\": \"#1E4FD8\"\n        }\n      ]\n    ]\n  }\n}\n",
  "babel.config.js": "module.exports = function (api) {\n  api.cache(true);\n  return {\n    presets: ['babel-preset-expo'],\n  };\n};\n",
  "eas.json": "{\n  \"cli\": {\n    \"version\": \">= 12.0.0\",\n    \"appVersionSource\": \"local\"\n  },\n  \"build\": {\n    \"development\": {\n      \"developmentClient\": true,\n      \"distribution\": \"internal\",\n      \"android\": {\n        \"buildType\": \"apk\"\n      }\n    },\n    \"preview\": {\n      \"distribution\": \"internal\",\n      \"android\": {\n        \"buildType\": \"apk\"\n      }\n    },\n    \"production\": {\n      \"android\": {\n        \"buildType\": \"apk\"\n      }\n    }\n  },\n  \"submit\": {\n    \"production\": {}\n  }\n}\n",
  "package.json": "{\n  \"name\": \"tecsolv\",\n  \"version\": \"1.0.0\",\n  \"main\": \"node_modules/expo/AppEntry.js\",\n  \"scripts\": {\n    \"start\": \"expo start\",\n    \"android\": \"expo start --android\",\n    \"build:apk\": \"eas build -p android --profile preview\",\n    \"subir\": \"node scripts/subir-a-github.js\",\n    \"actualizar\": \"node scripts/actualizar.js\"\n  },\n  \"dependencies\": {\n    \"@react-native-async-storage/async-storage\": \"1.23.1\",\n    \"@react-native-community/datetimepicker\": \"8.2.0\",\n    \"@react-navigation/native\": \"6.1.18\",\n    \"@react-navigation/native-stack\": \"6.11.0\",\n    \"expo\": \"52.0.46\",\n    \"expo-constants\": \"17.0.8\",\n    \"expo-crypto\": \"14.0.2\",\n    \"expo-notifications\": \"0.29.14\",\n    \"expo-status-bar\": \"2.0.1\",\n    \"react\": \"18.3.1\",\n    \"react-native\": \"0.76.9\",\n    \"react-native-safe-area-context\": \"4.12.0\",\n    \"react-native-screens\": \"4.4.0\"\n  },\n  \"devDependencies\": {\n    \"@babel/core\": \"7.25.2\"\n  },\n  \"private\": true\n}\n",
  "theme.js": "export const colors = {\n  primary: '#1E4FD8',\n  primaryDark: '#163A9E',\n  background: '#F4F6FB',\n  surface: '#FFFFFF',\n  text: '#1B1F2A',\n  muted: '#6B7280',\n  border: '#D5DAE5',\n  error: '#D93025',\n  errorBg: '#FDECEA',\n  success: '#1E8E3E',\n};\n\nexport const spacing = {\n  xs: 4,\n  sm: 8,\n  md: 16,\n  lg: 24,\n  xl: 32,\n};\n",
  ".github/workflows/build-apk.yml": "name: Build APK y publicar release\n\non:\n  push:\n    branches: [main]\n  workflow_dispatch:\n\npermissions:\n  contents: write\n\njobs:\n  build:\n    runs-on: ubuntu-latest\n    timeout-minutes: 60\n    env:\n      BUILD_NUMBER: ${{ github.run_number }}\n    steps:\n      - name: Descargar código\n        uses: actions/checkout@v4\n\n      - name: Instalar Node\n        uses: actions/setup-node@v4\n        with:\n          node-version: 20\n\n      - name: Instalar Java\n        uses: actions/setup-java@v4\n        with:\n          distribution: temurin\n          java-version: 17\n\n      - name: Instalar dependencias\n        run: npm install\n\n      - name: Generar proyecto Android\n        run: npx expo prebuild --platform android --no-install --clean\n\n      - name: Compilar APK\n        working-directory: android\n        run: ./gradlew assembleRelease --no-daemon -PreactNativeArchitectures=arm64-v8a,armeabi-v7a\n\n      - name: Renombrar APK\n        run: cp android/app/build/outputs/apk/release/app-release.apk TecSolv.apk\n\n      - name: Publicar release\n        uses: softprops/action-gh-release@v2\n        with:\n          tag_name: build-${{ github.run_number }}\n          name: TecSolv build ${{ github.run_number }}\n          body: |\n            Cambios incluidos en el commit ${{ github.sha }}.\n            Descarga el archivo TecSolv.apk e instálalo en tu Android.\n          files: TecSolv.apk\n          make_latest: true\n",
  "components/FormInput.js": "import React, { forwardRef, useState } from 'react';\nimport { Pressable, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { colors, spacing } from '../theme';\n\nconst FormInput = forwardRef(function FormInput(\n  { label, error, secure = false, style, inputStyle, ...props },\n  ref\n) {\n  const [visible, setVisible] = useState(false);\n  const [enfocado, setEnfocado] = useState(false);\n\n  return (\n    <View style={[styles.contenedor, style]}>\n      <Text style={styles.label}>{label}</Text>\n      <View\n        style={[\n          styles.campo,\n          enfocado && styles.campoEnfocado,\n          !!error && styles.campoError,\n        ]}\n      >\n        <TextInput\n          ref={ref}\n          style={[styles.input, inputStyle]}\n          placeholderTextColor={colors.muted}\n          secureTextEntry={secure && !visible}\n          autoCapitalize=\"none\"\n          onFocus={() => setEnfocado(true)}\n          onBlur={() => setEnfocado(false)}\n          {...props}\n        />\n        {secure && (\n          <Pressable\n            onPress={() => setVisible((v) => !v)}\n            hitSlop={10}\n            accessibilityRole=\"button\"\n            accessibilityLabel={visible ? 'Ocultar contraseña' : 'Mostrar contraseña'}\n          >\n            <Text style={styles.toggle}>{visible ? 'Ocultar' : 'Mostrar'}</Text>\n          </Pressable>\n        )}\n      </View>\n      {!!error && <Text style={styles.error}>{error}</Text>}\n    </View>\n  );\n});\n\nexport default FormInput;\n\nconst styles = StyleSheet.create({\n  contenedor: {\n    marginBottom: spacing.md,\n  },\n  label: {\n    fontSize: 14,\n    fontWeight: '600',\n    color: colors.text,\n    marginBottom: spacing.xs,\n  },\n  campo: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    backgroundColor: colors.surface,\n    borderWidth: 1,\n    borderColor: colors.border,\n    borderRadius: 10,\n    paddingHorizontal: 14,\n  },\n  campoEnfocado: {\n    borderColor: colors.primary,\n  },\n  campoError: {\n    borderColor: colors.error,\n  },\n  input: {\n    flex: 1,\n    height: 48,\n    fontSize: 16,\n    color: colors.text,\n  },\n  toggle: {\n    color: colors.primary,\n    fontWeight: '600',\n    fontSize: 13,\n    marginLeft: spacing.sm,\n  },\n  error: {\n    color: colors.error,\n    fontSize: 12,\n    marginTop: spacing.xs,\n  },\n});\n",
  "components/TaskCard.js": "import React from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\nimport { colors, spacing } from '../theme';\nimport {\n  ESTADO_COLORES,\n  PRIORIDAD_COLORES,\n  estaVencida,\n  formatearFechaHora,\n} from '../utils/taskUtils';\n\nexport default function TaskCard({ tarea, onPress, onToggle, onDelete }) {\n  const finalizada = tarea.estado === 'Finalizada';\n  const vencida = estaVencida(tarea);\n  const prioridad = PRIORIDAD_COLORES[tarea.prioridad];\n  const estado = ESTADO_COLORES[tarea.estado];\n\n  return (\n    <Pressable\n      style={({ pressed }) => [styles.tarjeta, pressed && styles.presionada]}\n      onPress={() => onPress(tarea)}\n      accessibilityRole=\"button\"\n      accessibilityLabel={`Editar tarea ${tarea.titulo}`}\n    >\n      <Pressable\n        onPress={() => onToggle(tarea)}\n        hitSlop={10}\n        style={[styles.check, finalizada && styles.checkActivo]}\n        accessibilityRole=\"checkbox\"\n        accessibilityState={{ checked: finalizada }}\n        accessibilityLabel={finalizada ? 'Marcar como pendiente' : 'Marcar como finalizada'}\n      >\n        {finalizada && <Text style={styles.checkTexto}>✓</Text>}\n      </Pressable>\n\n      <View style={styles.cuerpo}>\n        <Text style={[styles.titulo, finalizada && styles.tituloTachado]} numberOfLines={2}>\n          {tarea.titulo}\n        </Text>\n        <Text style={styles.materia} numberOfLines={1}>\n          {tarea.materia}\n        </Text>\n        <Text style={[styles.fecha, vencida && styles.fechaVencida]}>\n          {vencida ? 'Vencida · ' : ''}\n          {formatearFechaHora(tarea.fechaLimite)}\n        </Text>\n        <View style={styles.etiquetas}>\n          <View style={[styles.etiqueta, { backgroundColor: prioridad.bg }]}>\n            <Text style={[styles.etiquetaTexto, { color: prioridad.fg }]}>\n              Prioridad {tarea.prioridad}\n            </Text>\n          </View>\n          <View style={[styles.etiqueta, { backgroundColor: estado.bg }]}>\n            <Text style={[styles.etiquetaTexto, { color: estado.fg }]}>{tarea.estado}</Text>\n          </View>\n        </View>\n      </View>\n\n      <Pressable\n        onPress={() => onDelete(tarea)}\n        hitSlop={10}\n        style={styles.eliminar}\n        accessibilityRole=\"button\"\n        accessibilityLabel={`Eliminar tarea ${tarea.titulo}`}\n      >\n        <Text style={styles.eliminarTexto}>✕</Text>\n      </Pressable>\n    </Pressable>\n  );\n}\n\nconst styles = StyleSheet.create({\n  tarjeta: {\n    flexDirection: 'row',\n    alignItems: 'flex-start',\n    backgroundColor: colors.surface,\n    borderRadius: 14,\n    padding: spacing.md,\n    marginBottom: spacing.sm + 2,\n    elevation: 2,\n    shadowColor: '#000',\n    shadowOpacity: 0.06,\n    shadowRadius: 6,\n    shadowOffset: { width: 0, height: 2 },\n  },\n  presionada: {\n    opacity: 0.85,\n  },\n  check: {\n    width: 26,\n    height: 26,\n    borderRadius: 13,\n    borderWidth: 2,\n    borderColor: colors.border,\n    alignItems: 'center',\n    justifyContent: 'center',\n    marginRight: spacing.md,\n    marginTop: 2,\n  },\n  checkActivo: {\n    backgroundColor: colors.success,\n    borderColor: colors.success,\n  },\n  checkTexto: {\n    color: '#FFFFFF',\n    fontSize: 14,\n    fontWeight: '800',\n  },\n  cuerpo: {\n    flex: 1,\n  },\n  titulo: {\n    fontSize: 16,\n    fontWeight: '700',\n    color: colors.text,\n  },\n  tituloTachado: {\n    textDecorationLine: 'line-through',\n    color: colors.muted,\n  },\n  materia: {\n    fontSize: 13,\n    color: colors.primary,\n    fontWeight: '600',\n    marginTop: 2,\n  },\n  fecha: {\n    fontSize: 13,\n    color: colors.muted,\n    marginTop: spacing.xs,\n  },\n  fechaVencida: {\n    color: colors.error,\n    fontWeight: '600',\n  },\n  etiquetas: {\n    flexDirection: 'row',\n    flexWrap: 'wrap',\n    marginTop: spacing.sm,\n  },\n  etiqueta: {\n    borderRadius: 20,\n    paddingHorizontal: 10,\n    paddingVertical: 3,\n    marginRight: spacing.sm,\n    marginBottom: spacing.xs,\n  },\n  etiquetaTexto: {\n    fontSize: 11,\n    fontWeight: '700',\n  },\n  eliminar: {\n    marginLeft: spacing.sm,\n    padding: spacing.xs,\n  },\n  eliminarTexto: {\n    color: colors.muted,\n    fontSize: 16,\n    fontWeight: '700',\n  },\n});\n",
  "components/UpdateChecker.js": "import { useEffect } from 'react';\nimport { Alert, Linking } from 'react-native';\nimport { buscarActualizacion } from '../services/updateService';\n\nexport default function UpdateChecker() {\n  useEffect(() => {\n    let activo = true;\n    buscarActualizacion()\n      .then((nueva) => {\n        if (!activo || !nueva) return;\n        Alert.alert(\n          'Actualización disponible',\n          `Hay una nueva versión de TecSolv (${nueva.nombre}). ¿Quieres descargarla ahora?`,\n          [\n            { text: 'Más tarde', style: 'cancel' },\n            {\n              text: 'Descargar',\n              onPress: () => {\n                Linking.openURL(nueva.url).catch(() => {});\n              },\n            },\n          ]\n        );\n      })\n      .catch(() => {});\n    return () => {\n      activo = false;\n    };\n  }, []);\n\n  return null;\n}\n",
  "context/AuthContext.js": "import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';\nimport {\n  cerrarSesion,\n  iniciarSesion,\n  obtenerSesion,\n  registrarUsuario,\n} from '../services/authService';\n\nconst AuthContext = createContext(null);\n\nexport function AuthProvider({ children }) {\n  const [usuario, setUsuario] = useState(null);\n  const [cargando, setCargando] = useState(true);\n\n  useEffect(() => {\n    let activo = true;\n    (async () => {\n      try {\n        const sesion = await obtenerSesion();\n        if (activo) setUsuario(sesion);\n      } catch (e) {\n        if (activo) setUsuario(null);\n      } finally {\n        if (activo) setCargando(false);\n      }\n    })();\n    return () => {\n      activo = false;\n    };\n  }, []);\n\n  const login = useCallback(async (datos) => {\n    const sesion = await iniciarSesion(datos);\n    setUsuario(sesion);\n  }, []);\n\n  const registro = useCallback(async (datos) => {\n    const sesion = await registrarUsuario(datos);\n    setUsuario(sesion);\n  }, []);\n\n  const logout = useCallback(async () => {\n    await cerrarSesion();\n    setUsuario(null);\n  }, []);\n\n  const valor = useMemo(\n    () => ({ usuario, cargando, login, registro, logout }),\n    [usuario, cargando, login, registro, logout]\n  );\n\n  return <AuthContext.Provider value={valor}>{children}</AuthContext.Provider>;\n}\n\nexport function useAuth() {\n  const ctx = useContext(AuthContext);\n  if (!ctx) {\n    throw new Error('useAuth debe usarse dentro de un AuthProvider');\n  }\n  return ctx;\n}\n",
  "context/TasksContext.js": "import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';\nimport { useAuth } from './AuthContext';\nimport {\n  actualizarTarea,\n  crearTarea,\n  eliminarTarea,\n  obtenerTareas,\n} from '../services/taskService';\n\nconst TasksContext = createContext(null);\n\nexport function TasksProvider({ children }) {\n  const { usuario } = useAuth();\n  const userId = usuario ? usuario.id : null;\n  const [tareas, setTareas] = useState([]);\n  const [cargando, setCargando] = useState(false);\n\n  useEffect(() => {\n    let activo = true;\n    if (!userId) {\n      setTareas([]);\n      setCargando(false);\n      return undefined;\n    }\n    setCargando(true);\n    obtenerTareas(userId)\n      .then((lista) => {\n        if (activo) setTareas(lista);\n      })\n      .catch(() => {\n        if (activo) setTareas([]);\n      })\n      .finally(() => {\n        if (activo) setCargando(false);\n      });\n    return () => {\n      activo = false;\n    };\n  }, [userId]);\n\n  const crear = useCallback(\n    async (datos) => {\n      const { lista, tarea } = await crearTarea(userId, datos);\n      setTareas(lista);\n      return tarea;\n    },\n    [userId]\n  );\n\n  const actualizar = useCallback(\n    async (id, cambios) => {\n      const { lista, tarea } = await actualizarTarea(userId, id, cambios);\n      setTareas(lista);\n      return tarea;\n    },\n    [userId]\n  );\n\n  const eliminar = useCallback(\n    async (id) => {\n      const lista = await eliminarTarea(userId, id);\n      setTareas(lista);\n    },\n    [userId]\n  );\n\n  const valor = useMemo(\n    () => ({ tareas, cargando, crear, actualizar, eliminar }),\n    [tareas, cargando, crear, actualizar, eliminar]\n  );\n\n  return <TasksContext.Provider value={valor}>{children}</TasksContext.Provider>;\n}\n\nexport function useTasks() {\n  const ctx = useContext(TasksContext);\n  if (!ctx) {\n    throw new Error('useTasks debe usarse dentro de un TasksProvider');\n  }\n  return ctx;\n}\n",
  "navigation/AppNavigator.js": "import React from 'react';\nimport { ActivityIndicator, View } from 'react-native';\nimport { NavigationContainer, DefaultTheme } from '@react-navigation/native';\nimport { createNativeStackNavigator } from '@react-navigation/native-stack';\nimport { useAuth } from '../context/AuthContext';\nimport LoginScreen from '../screens/LoginScreen';\nimport RegisterScreen from '../screens/RegisterScreen';\nimport HomeScreen from '../screens/HomeScreen';\nimport TaskFormScreen from '../screens/TaskFormScreen';\nimport { colors } from '../theme';\n\nconst Stack = createNativeStackNavigator();\n\nconst tema = {\n  ...DefaultTheme,\n  colors: {\n    ...DefaultTheme.colors,\n    primary: colors.primary,\n    background: colors.background,\n    card: colors.surface,\n    text: colors.text,\n    border: colors.border,\n  },\n};\n\nexport default function AppNavigator() {\n  const { usuario, cargando } = useAuth();\n\n  if (cargando) {\n    return (\n      <View\n        style={{\n          flex: 1,\n          alignItems: 'center',\n          justifyContent: 'center',\n          backgroundColor: colors.background,\n        }}\n      >\n        <ActivityIndicator size=\"large\" color={colors.primary} />\n      </View>\n    );\n  }\n\n  return (\n    <NavigationContainer theme={tema}>\n      <Stack.Navigator\n        screenOptions={{\n          headerTintColor: colors.primary,\n          headerTitleStyle: { color: colors.text },\n        }}\n      >\n        {usuario ? (\n          <>\n            <Stack.Screen\n              name=\"Home\"\n              component={HomeScreen}\n              options={{ title: 'Mis tareas' }}\n            />\n            <Stack.Screen\n              name=\"TaskForm\"\n              component={TaskFormScreen}\n              options={{ title: 'Tarea', headerBackTitle: 'Atrás' }}\n            />\n          </>\n        ) : (\n          <>\n            <Stack.Screen\n              name=\"Login\"\n              component={LoginScreen}\n              options={{ headerShown: false }}\n            />\n            <Stack.Screen\n              name=\"Register\"\n              component={RegisterScreen}\n              options={{ title: 'Registro', headerBackTitle: 'Atrás' }}\n            />\n          </>\n        )}\n      </Stack.Navigator>\n    </NavigationContainer>\n  );\n}\n",
  "screens/HomeScreen.js": "import React, { useCallback, useLayoutEffect, useMemo, useState } from 'react';\nimport {\n  ActivityIndicator,\n  Alert,\n  Pressable,\n  ScrollView,\n  SectionList,\n  StyleSheet,\n  Text,\n  TextInput,\n  View,\n} from 'react-native';\nimport TaskCard from '../components/TaskCard';\nimport { useAuth } from '../context/AuthContext';\nimport { useTasks } from '../context/TasksContext';\nimport { colors, spacing } from '../theme';\nimport { agruparTareas, contarPorEstado, estaVencida, filtrarTareas } from '../utils/taskUtils';\n\nconst FILTROS = ['Todas', 'Pendiente', 'En Progreso', 'Finalizada'];\n\nexport default function HomeScreen({ navigation }) {\n  const { usuario, logout } = useAuth();\n  const { tareas, cargando, actualizar, eliminar } = useTasks();\n  const [busqueda, setBusqueda] = useState('');\n  const [filtro, setFiltro] = useState('Todas');\n\n  const confirmarSalida = useCallback(() => {\n    Alert.alert('Cerrar sesión', '¿Deseas cerrar tu sesión?', [\n      { text: 'Cancelar', style: 'cancel' },\n      { text: 'Cerrar sesión', style: 'destructive', onPress: () => logout() },\n    ]);\n  }, [logout]);\n\n  useLayoutEffect(() => {\n    navigation.setOptions({\n      headerRight: () => (\n        <Pressable onPress={confirmarSalida} hitSlop={10} accessibilityRole=\"button\">\n          <Text style={styles.salir}>Salir</Text>\n        </Pressable>\n      ),\n    });\n  }, [navigation, confirmarSalida]);\n\n  const conteo = useMemo(() => contarPorEstado(tareas), [tareas]);\n  const vencidas = useMemo(() => tareas.filter(estaVencida).length, [tareas]);\n  const secciones = useMemo(\n    () => agruparTareas(filtrarTareas(tareas, { estado: filtro, busqueda })),\n    [tareas, filtro, busqueda]\n  );\n\n  const abrirFormulario = (tarea) => navigation.navigate('TaskForm', tarea ? { tarea } : {});\n\n  const alternarEstado = async (tarea) => {\n    try {\n      await actualizar(tarea.id, {\n        estado: tarea.estado === 'Finalizada' ? 'Pendiente' : 'Finalizada',\n      });\n    } catch (e) {\n      Alert.alert('Error', e.message || 'No se pudo actualizar la tarea.');\n    }\n  };\n\n  const confirmarEliminar = (tarea) => {\n    Alert.alert('Eliminar tarea', `¿Eliminar \"${tarea.titulo}\"? Esta acción no se puede deshacer.`, [\n      { text: 'Cancelar', style: 'cancel' },\n      {\n        text: 'Eliminar',\n        style: 'destructive',\n        onPress: async () => {\n          try {\n            await eliminar(tarea.id);\n          } catch (e) {\n            Alert.alert('Error', e.message || 'No se pudo eliminar la tarea.');\n          }\n        },\n      },\n    ]);\n  };\n\n  const hayFiltros = filtro !== 'Todas' || busqueda.trim().length > 0;\n\n  const encabezado = (\n    <View>\n      <Text style={styles.saludo}>Hola, {usuario ? usuario.nombre.split(' ')[0] : ''}</Text>\n      <View style={styles.resumen}>\n        <View style={styles.resumenItem}>\n          <Text style={styles.resumenNumero}>{conteo.Pendiente + conteo['En Progreso']}</Text>\n          <Text style={styles.resumenTexto}>Activas</Text>\n        </View>\n        <View style={styles.resumenItem}>\n          <Text style={[styles.resumenNumero, vencidas > 0 && { color: colors.error }]}>\n            {vencidas}\n          </Text>\n          <Text style={styles.resumenTexto}>Vencidas</Text>\n        </View>\n        <View style={styles.resumenItem}>\n          <Text style={[styles.resumenNumero, { color: colors.success }]}>{conteo.Finalizada}</Text>\n          <Text style={styles.resumenTexto}>Finalizadas</Text>\n        </View>\n      </View>\n\n      <TextInput\n        style={styles.buscador}\n        placeholder=\"Buscar por título, materia o descripción\"\n        placeholderTextColor={colors.muted}\n        value={busqueda}\n        onChangeText={setBusqueda}\n        returnKeyType=\"search\"\n        autoCorrect={false}\n        clearButtonMode=\"while-editing\"\n      />\n\n      <ScrollView\n        horizontal\n        showsHorizontalScrollIndicator={false}\n        contentContainerStyle={styles.filtros}\n        keyboardShouldPersistTaps=\"handled\"\n      >\n        {FILTROS.map((f) => {\n          const activo = filtro === f;\n          return (\n            <Pressable\n              key={f}\n              onPress={() => setFiltro(f)}\n              style={[styles.chip, activo && styles.chipActivo]}\n              accessibilityRole=\"button\"\n              accessibilityState={{ selected: activo }}\n            >\n              <Text style={[styles.chipTexto, activo && styles.chipTextoActivo]}>\n                {f} ({conteo[f]})\n              </Text>\n            </Pressable>\n          );\n        })}\n      </ScrollView>\n    </View>\n  );\n\n  return (\n    <View style={styles.contenedor}>\n      {cargando ? (\n        <View style={styles.centrado}>\n          <ActivityIndicator size=\"large\" color={colors.primary} />\n        </View>\n      ) : (\n        <SectionList\n          sections={secciones}\n          keyExtractor={(item) => item.id}\n          ListHeaderComponent={encabezado}\n          stickySectionHeadersEnabled={false}\n          keyboardShouldPersistTaps=\"handled\"\n          contentContainerStyle={styles.lista}\n          renderSectionHeader={({ section }) => (\n            <View style={styles.seccion}>\n              <View style={[styles.seccionPunto, { backgroundColor: section.color }]} />\n              <Text style={[styles.seccionTitulo, { color: section.color }]}>{section.title}</Text>\n              <Text style={styles.seccionConteo}>{section.data.length}</Text>\n            </View>\n          )}\n          renderItem={({ item }) => (\n            <TaskCard\n              tarea={item}\n              onPress={abrirFormulario}\n              onToggle={alternarEstado}\n              onDelete={confirmarEliminar}\n            />\n          )}\n          ListEmptyComponent={\n            <View style={styles.vacio}>\n              <Text style={styles.vacioTitulo}>\n                {hayFiltros ? 'Sin resultados' : 'Aún no tienes tareas'}\n              </Text>\n              <Text style={styles.vacioTexto}>\n                {hayFiltros\n                  ? 'Prueba con otra búsqueda o cambia el filtro.'\n                  : 'Toca el botón + para registrar tu primera tarea académica.'}\n              </Text>\n            </View>\n          }\n        />\n      )}\n\n      <Pressable\n        style={({ pressed }) => [styles.fab, pressed && styles.fabPresionado]}\n        onPress={() => abrirFormulario(null)}\n        accessibilityRole=\"button\"\n        accessibilityLabel=\"Crear nueva tarea\"\n      >\n        <Text style={styles.fabTexto}>+</Text>\n      </Pressable>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  contenedor: {\n    flex: 1,\n    backgroundColor: colors.background,\n  },\n  centrado: {\n    flex: 1,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  lista: {\n    padding: spacing.md,\n    paddingBottom: 100,\n  },\n  salir: {\n    color: colors.primary,\n    fontWeight: '700',\n    fontSize: 15,\n  },\n  saludo: {\n    fontSize: 22,\n    fontWeight: '800',\n    color: colors.text,\n    marginBottom: spacing.md,\n  },\n  resumen: {\n    flexDirection: 'row',\n    backgroundColor: colors.surface,\n    borderRadius: 14,\n    paddingVertical: spacing.md,\n    marginBottom: spacing.md,\n    elevation: 2,\n    shadowColor: '#000',\n    shadowOpacity: 0.06,\n    shadowRadius: 6,\n    shadowOffset: { width: 0, height: 2 },\n  },\n  resumenItem: {\n    flex: 1,\n    alignItems: 'center',\n  },\n  resumenNumero: {\n    fontSize: 24,\n    fontWeight: '800',\n    color: colors.primary,\n  },\n  resumenTexto: {\n    fontSize: 12,\n    color: colors.muted,\n    marginTop: 2,\n  },\n  buscador: {\n    backgroundColor: colors.surface,\n    borderWidth: 1,\n    borderColor: colors.border,\n    borderRadius: 10,\n    height: 46,\n    paddingHorizontal: 14,\n    fontSize: 15,\n    color: colors.text,\n  },\n  filtros: {\n    paddingVertical: spacing.md,\n  },\n  chip: {\n    paddingHorizontal: 14,\n    paddingVertical: 8,\n    borderRadius: 20,\n    backgroundColor: colors.surface,\n    borderWidth: 1,\n    borderColor: colors.border,\n    marginRight: spacing.sm,\n  },\n  chipActivo: {\n    backgroundColor: colors.primary,\n    borderColor: colors.primary,\n  },\n  chipTexto: {\n    fontSize: 13,\n    fontWeight: '600',\n    color: colors.text,\n  },\n  chipTextoActivo: {\n    color: '#FFFFFF',\n  },\n  seccion: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    marginTop: spacing.sm,\n    marginBottom: spacing.sm,\n  },\n  seccionPunto: {\n    width: 8,\n    height: 8,\n    borderRadius: 4,\n    marginRight: spacing.sm,\n  },\n  seccionTitulo: {\n    fontSize: 14,\n    fontWeight: '800',\n    textTransform: 'uppercase',\n    letterSpacing: 0.5,\n  },\n  seccionConteo: {\n    fontSize: 12,\n    color: colors.muted,\n    marginLeft: spacing.sm,\n    fontWeight: '600',\n  },\n  vacio: {\n    alignItems: 'center',\n    paddingVertical: spacing.xl,\n    paddingHorizontal: spacing.lg,\n  },\n  vacioTitulo: {\n    fontSize: 17,\n    fontWeight: '700',\n    color: colors.text,\n  },\n  vacioTexto: {\n    fontSize: 14,\n    color: colors.muted,\n    textAlign: 'center',\n    marginTop: spacing.xs,\n  },\n  fab: {\n    position: 'absolute',\n    right: spacing.lg,\n    bottom: spacing.lg,\n    width: 60,\n    height: 60,\n    borderRadius: 30,\n    backgroundColor: colors.primary,\n    alignItems: 'center',\n    justifyContent: 'center',\n    elevation: 6,\n    shadowColor: '#000',\n    shadowOpacity: 0.25,\n    shadowRadius: 8,\n    shadowOffset: { width: 0, height: 4 },\n  },\n  fabPresionado: {\n    backgroundColor: colors.primaryDark,\n  },\n  fabTexto: {\n    color: '#FFFFFF',\n    fontSize: 32,\n    lineHeight: 34,\n    fontWeight: '400',\n  },\n});\n",
  "screens/LoginScreen.js": "import React, { useRef, useState } from 'react';\nimport {\n  ActivityIndicator,\n  KeyboardAvoidingView,\n  Platform,\n  Pressable,\n  ScrollView,\n  StyleSheet,\n  Text,\n  View,\n} from 'react-native';\nimport FormInput from '../components/FormInput';\nimport { useAuth } from '../context/AuthContext';\nimport { colors, spacing } from '../theme';\n\nconst EMAIL_REGEX = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/;\n\nexport default function LoginScreen({ navigation }) {\n  const { login } = useAuth();\n  const [email, setEmail] = useState('');\n  const [password, setPassword] = useState('');\n  const [errores, setErrores] = useState({});\n  const [errorGeneral, setErrorGeneral] = useState('');\n  const [enviando, setEnviando] = useState(false);\n  const passwordRef = useRef(null);\n\n  const validar = () => {\n    const nuevos = {};\n    if (!email.trim()) {\n      nuevos.email = 'Ingresa tu correo electrónico.';\n    } else if (!EMAIL_REGEX.test(email.trim())) {\n      nuevos.email = 'El correo no tiene un formato válido.';\n    }\n    if (!password) {\n      nuevos.password = 'Ingresa tu contraseña.';\n    } else if (password.length < 6) {\n      nuevos.password = 'La contraseña debe tener al menos 6 caracteres.';\n    }\n    setErrores(nuevos);\n    return Object.keys(nuevos).length === 0;\n  };\n\n  const manejarLogin = async () => {\n    setErrorGeneral('');\n    if (!validar()) return;\n    setEnviando(true);\n    try {\n      await login({ email, password });\n    } catch (e) {\n      setErrorGeneral(e.message || 'No se pudo iniciar sesión.');\n      setEnviando(false);\n    }\n  };\n\n  return (\n    <KeyboardAvoidingView\n      style={styles.flex}\n      behavior={Platform.OS === 'ios' ? 'padding' : undefined}\n    >\n      <ScrollView\n        contentContainerStyle={styles.scroll}\n        keyboardShouldPersistTaps=\"handled\"\n      >\n        <View style={styles.encabezado}>\n          <View style={styles.logo}>\n            <Text style={styles.logoTexto}>TS</Text>\n          </View>\n          <Text style={styles.titulo}>TecSolv</Text>\n          <Text style={styles.subtitulo}>Gestión de actividades académicas</Text>\n        </View>\n\n        <View style={styles.tarjeta}>\n          <Text style={styles.tituloForm}>Iniciar sesión</Text>\n\n          {!!errorGeneral && (\n            <View style={styles.banner}>\n              <Text style={styles.bannerTexto}>{errorGeneral}</Text>\n            </View>\n          )}\n\n          <FormInput\n            label=\"Correo electrónico\"\n            placeholder=\"correo@ejemplo.com\"\n            value={email}\n            onChangeText={setEmail}\n            error={errores.email}\n            keyboardType=\"email-address\"\n            autoComplete=\"email\"\n            returnKeyType=\"next\"\n            onSubmitEditing={() => passwordRef.current && passwordRef.current.focus()}\n            blurOnSubmit={false}\n          />\n\n          <FormInput\n            ref={passwordRef}\n            label=\"Contraseña\"\n            placeholder=\"Tu contraseña\"\n            value={password}\n            onChangeText={setPassword}\n            error={errores.password}\n            secure\n            autoComplete=\"password\"\n            returnKeyType=\"done\"\n            onSubmitEditing={manejarLogin}\n          />\n\n          <Pressable\n            style={({ pressed }) => [\n              styles.boton,\n              pressed && styles.botonPresionado,\n              enviando && styles.botonDeshabilitado,\n            ]}\n            onPress={manejarLogin}\n            disabled={enviando}\n            accessibilityRole=\"button\"\n          >\n            {enviando ? (\n              <ActivityIndicator color=\"#FFFFFF\" />\n            ) : (\n              <Text style={styles.botonTexto}>Entrar</Text>\n            )}\n          </Pressable>\n\n          <Pressable\n            onPress={() => navigation.navigate('Register')}\n            style={styles.enlace}\n            accessibilityRole=\"button\"\n          >\n            <Text style={styles.enlaceTexto}>\n              ¿No tienes cuenta? <Text style={styles.enlaceResaltado}>Regístrate</Text>\n            </Text>\n          </Pressable>\n        </View>\n      </ScrollView>\n    </KeyboardAvoidingView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  flex: {\n    flex: 1,\n    backgroundColor: colors.background,\n  },\n  scroll: {\n    flexGrow: 1,\n    justifyContent: 'center',\n    padding: spacing.lg,\n  },\n  encabezado: {\n    alignItems: 'center',\n    marginBottom: spacing.lg,\n  },\n  logo: {\n    width: 72,\n    height: 72,\n    borderRadius: 20,\n    backgroundColor: colors.primary,\n    alignItems: 'center',\n    justifyContent: 'center',\n    marginBottom: spacing.md,\n  },\n  logoTexto: {\n    color: '#FFFFFF',\n    fontSize: 28,\n    fontWeight: '800',\n  },\n  titulo: {\n    fontSize: 30,\n    fontWeight: '800',\n    color: colors.text,\n  },\n  subtitulo: {\n    fontSize: 14,\n    color: colors.muted,\n    marginTop: spacing.xs,\n  },\n  tarjeta: {\n    backgroundColor: colors.surface,\n    borderRadius: 16,\n    padding: spacing.lg,\n    elevation: 3,\n    shadowColor: '#000',\n    shadowOpacity: 0.08,\n    shadowRadius: 8,\n    shadowOffset: { width: 0, height: 3 },\n  },\n  tituloForm: {\n    fontSize: 20,\n    fontWeight: '700',\n    color: colors.text,\n    marginBottom: spacing.md,\n  },\n  banner: {\n    backgroundColor: colors.errorBg,\n    borderRadius: 8,\n    padding: spacing.sm + 2,\n    marginBottom: spacing.md,\n  },\n  bannerTexto: {\n    color: colors.error,\n    fontSize: 13,\n  },\n  boton: {\n    backgroundColor: colors.primary,\n    borderRadius: 10,\n    height: 50,\n    alignItems: 'center',\n    justifyContent: 'center',\n    marginTop: spacing.sm,\n  },\n  botonPresionado: {\n    backgroundColor: colors.primaryDark,\n  },\n  botonDeshabilitado: {\n    opacity: 0.7,\n  },\n  botonTexto: {\n    color: '#FFFFFF',\n    fontSize: 16,\n    fontWeight: '700',\n  },\n  enlace: {\n    alignItems: 'center',\n    marginTop: spacing.md,\n    paddingVertical: spacing.xs,\n  },\n  enlaceTexto: {\n    color: colors.muted,\n    fontSize: 14,\n  },\n  enlaceResaltado: {\n    color: colors.primary,\n    fontWeight: '700',\n  },\n});\n",
  "screens/RegisterScreen.js": "import React, { useRef, useState } from 'react';\nimport {\n  ActivityIndicator,\n  KeyboardAvoidingView,\n  Platform,\n  Pressable,\n  ScrollView,\n  StyleSheet,\n  Text,\n  View,\n} from 'react-native';\nimport FormInput from '../components/FormInput';\nimport { useAuth } from '../context/AuthContext';\nimport { colors, spacing } from '../theme';\n\nconst EMAIL_REGEX = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/;\n\nexport default function RegisterScreen({ navigation }) {\n  const { registro } = useAuth();\n  const [nombre, setNombre] = useState('');\n  const [email, setEmail] = useState('');\n  const [password, setPassword] = useState('');\n  const [confirmar, setConfirmar] = useState('');\n  const [errores, setErrores] = useState({});\n  const [errorGeneral, setErrorGeneral] = useState('');\n  const [enviando, setEnviando] = useState(false);\n\n  const emailRef = useRef(null);\n  const passwordRef = useRef(null);\n  const confirmarRef = useRef(null);\n\n  const validar = () => {\n    const nuevos = {};\n\n    if (!nombre.trim()) {\n      nuevos.nombre = 'Ingresa tu nombre.';\n    } else if (nombre.trim().length < 3) {\n      nuevos.nombre = 'El nombre debe tener al menos 3 caracteres.';\n    }\n\n    if (!email.trim()) {\n      nuevos.email = 'Ingresa tu correo electrónico.';\n    } else if (!EMAIL_REGEX.test(email.trim())) {\n      nuevos.email = 'El correo no tiene un formato válido.';\n    }\n\n    if (!password) {\n      nuevos.password = 'Ingresa una contraseña.';\n    } else if (password.length < 8) {\n      nuevos.password = 'La contraseña debe tener al menos 8 caracteres.';\n    } else if (!/[A-Za-z]/.test(password) || !/[0-9]/.test(password)) {\n      nuevos.password = 'Debe incluir al menos una letra y un número.';\n    }\n\n    if (!confirmar) {\n      nuevos.confirmar = 'Confirma tu contraseña.';\n    } else if (confirmar !== password) {\n      nuevos.confirmar = 'Las contraseñas no coinciden.';\n    }\n\n    setErrores(nuevos);\n    return Object.keys(nuevos).length === 0;\n  };\n\n  const manejarRegistro = async () => {\n    setErrorGeneral('');\n    if (!validar()) return;\n    setEnviando(true);\n    try {\n      await registro({ nombre, email, password });\n    } catch (e) {\n      setErrorGeneral(e.message || 'No se pudo crear la cuenta.');\n      setEnviando(false);\n    }\n  };\n\n  return (\n    <KeyboardAvoidingView\n      style={styles.flex}\n      behavior={Platform.OS === 'ios' ? 'padding' : undefined}\n    >\n      <ScrollView\n        contentContainerStyle={styles.scroll}\n        keyboardShouldPersistTaps=\"handled\"\n      >\n        <View style={styles.tarjeta}>\n          <Text style={styles.tituloForm}>Crear cuenta</Text>\n          <Text style={styles.descripcion}>\n            Regístrate para organizar tus tareas y fechas de entrega.\n          </Text>\n\n          {!!errorGeneral && (\n            <View style={styles.banner}>\n              <Text style={styles.bannerTexto}>{errorGeneral}</Text>\n            </View>\n          )}\n\n          <FormInput\n            label=\"Nombre completo\"\n            placeholder=\"Tu nombre\"\n            value={nombre}\n            onChangeText={setNombre}\n            error={errores.nombre}\n            autoCapitalize=\"words\"\n            autoComplete=\"name\"\n            returnKeyType=\"next\"\n            onSubmitEditing={() => emailRef.current && emailRef.current.focus()}\n            blurOnSubmit={false}\n          />\n\n          <FormInput\n            ref={emailRef}\n            label=\"Correo electrónico\"\n            placeholder=\"correo@ejemplo.com\"\n            value={email}\n            onChangeText={setEmail}\n            error={errores.email}\n            keyboardType=\"email-address\"\n            autoComplete=\"email\"\n            returnKeyType=\"next\"\n            onSubmitEditing={() => passwordRef.current && passwordRef.current.focus()}\n            blurOnSubmit={false}\n          />\n\n          <FormInput\n            ref={passwordRef}\n            label=\"Contraseña\"\n            placeholder=\"Mínimo 8 caracteres\"\n            value={password}\n            onChangeText={setPassword}\n            error={errores.password}\n            secure\n            autoComplete=\"new-password\"\n            returnKeyType=\"next\"\n            onSubmitEditing={() => confirmarRef.current && confirmarRef.current.focus()}\n            blurOnSubmit={false}\n          />\n\n          <FormInput\n            ref={confirmarRef}\n            label=\"Confirmar contraseña\"\n            placeholder=\"Repite tu contraseña\"\n            value={confirmar}\n            onChangeText={setConfirmar}\n            error={errores.confirmar}\n            secure\n            autoComplete=\"new-password\"\n            returnKeyType=\"done\"\n            onSubmitEditing={manejarRegistro}\n          />\n\n          <Pressable\n            style={({ pressed }) => [\n              styles.boton,\n              pressed && styles.botonPresionado,\n              enviando && styles.botonDeshabilitado,\n            ]}\n            onPress={manejarRegistro}\n            disabled={enviando}\n            accessibilityRole=\"button\"\n          >\n            {enviando ? (\n              <ActivityIndicator color=\"#FFFFFF\" />\n            ) : (\n              <Text style={styles.botonTexto}>Crear cuenta</Text>\n            )}\n          </Pressable>\n\n          <Pressable\n            onPress={() => navigation.goBack()}\n            style={styles.enlace}\n            accessibilityRole=\"button\"\n          >\n            <Text style={styles.enlaceTexto}>\n              ¿Ya tienes cuenta? <Text style={styles.enlaceResaltado}>Inicia sesión</Text>\n            </Text>\n          </Pressable>\n        </View>\n      </ScrollView>\n    </KeyboardAvoidingView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  flex: {\n    flex: 1,\n    backgroundColor: colors.background,\n  },\n  scroll: {\n    flexGrow: 1,\n    justifyContent: 'center',\n    padding: spacing.lg,\n  },\n  tarjeta: {\n    backgroundColor: colors.surface,\n    borderRadius: 16,\n    padding: spacing.lg,\n    elevation: 3,\n    shadowColor: '#000',\n    shadowOpacity: 0.08,\n    shadowRadius: 8,\n    shadowOffset: { width: 0, height: 3 },\n  },\n  tituloForm: {\n    fontSize: 20,\n    fontWeight: '700',\n    color: colors.text,\n  },\n  descripcion: {\n    fontSize: 13,\n    color: colors.muted,\n    marginTop: spacing.xs,\n    marginBottom: spacing.md,\n  },\n  banner: {\n    backgroundColor: colors.errorBg,\n    borderRadius: 8,\n    padding: spacing.sm + 2,\n    marginBottom: spacing.md,\n  },\n  bannerTexto: {\n    color: colors.error,\n    fontSize: 13,\n  },\n  boton: {\n    backgroundColor: colors.primary,\n    borderRadius: 10,\n    height: 50,\n    alignItems: 'center',\n    justifyContent: 'center',\n    marginTop: spacing.sm,\n  },\n  botonPresionado: {\n    backgroundColor: colors.primaryDark,\n  },\n  botonDeshabilitado: {\n    opacity: 0.7,\n  },\n  botonTexto: {\n    color: '#FFFFFF',\n    fontSize: 16,\n    fontWeight: '700',\n  },\n  enlace: {\n    alignItems: 'center',\n    marginTop: spacing.md,\n    paddingVertical: spacing.xs,\n  },\n  enlaceTexto: {\n    color: colors.muted,\n    fontSize: 14,\n  },\n  enlaceResaltado: {\n    color: colors.primary,\n    fontWeight: '700',\n  },\n});\n",
  "screens/TaskFormScreen.js": "import React, { useLayoutEffect, useRef, useState } from 'react';\nimport {\n  ActivityIndicator,\n  Alert,\n  KeyboardAvoidingView,\n  Platform,\n  Pressable,\n  ScrollView,\n  StyleSheet,\n  Text,\n  View,\n} from 'react-native';\nimport DateTimePicker, { DateTimePickerAndroid } from '@react-native-community/datetimepicker';\nimport FormInput from '../components/FormInput';\nimport { useTasks } from '../context/TasksContext';\nimport { colors, spacing } from '../theme';\nimport {\n  ESTADOS,\n  ESTADO_COLORES,\n  PRIORIDADES,\n  PRIORIDAD_COLORES,\n  formatearFecha,\n  formatearHora,\n} from '../utils/taskUtils';\n\nconst fechaPorDefecto = () => {\n  const d = new Date();\n  d.setDate(d.getDate() + 1);\n  d.setHours(23, 59, 0, 0);\n  return d;\n};\n\nexport default function TaskFormScreen({ navigation, route }) {\n  const tareaEditar = route.params && route.params.tarea ? route.params.tarea : null;\n  const { crear, actualizar, eliminar } = useTasks();\n\n  const [titulo, setTitulo] = useState(tareaEditar ? tareaEditar.titulo : '');\n  const [descripcion, setDescripcion] = useState(tareaEditar ? tareaEditar.descripcion : '');\n  const [materia, setMateria] = useState(tareaEditar ? tareaEditar.materia : '');\n  const [fecha, setFecha] = useState(\n    tareaEditar ? new Date(tareaEditar.fechaLimite) : fechaPorDefecto()\n  );\n  const [prioridad, setPrioridad] = useState(tareaEditar ? tareaEditar.prioridad : 'Media');\n  const [estado, setEstado] = useState(tareaEditar ? tareaEditar.estado : 'Pendiente');\n  const [errores, setErrores] = useState({});\n  const [guardando, setGuardando] = useState(false);\n\n  const materiaRef = useRef(null);\n  const descripcionRef = useRef(null);\n\n  useLayoutEffect(() => {\n    navigation.setOptions({ title: tareaEditar ? 'Editar tarea' : 'Nueva tarea' });\n  }, [navigation, tareaEditar]);\n\n  const limpiarError = (campo) => setErrores((prev) => ({ ...prev, [campo]: undefined }));\n\n  const abrirSelectorAndroid = () => {\n    DateTimePickerAndroid.open({\n      value: fecha,\n      mode: 'date',\n      onChange: (eventoFecha, fechaElegida) => {\n        if (eventoFecha.type !== 'set' || !fechaElegida) return;\n        DateTimePickerAndroid.open({\n          value: fechaElegida,\n          mode: 'time',\n          is24Hour: true,\n          onChange: (eventoHora, horaElegida) => {\n            if (eventoHora.type !== 'set' || !horaElegida) return;\n            setFecha(horaElegida);\n            limpiarError('fecha');\n          },\n        });\n      },\n    });\n  };\n\n  const validar = () => {\n    const nuevos = {};\n\n    if (!titulo.trim()) {\n      nuevos.titulo = 'Ingresa el título de la tarea.';\n    } else if (titulo.trim().length < 3) {\n      nuevos.titulo = 'El título debe tener al menos 3 caracteres.';\n    } else if (titulo.trim().length > 80) {\n      nuevos.titulo = 'El título no debe exceder 80 caracteres.';\n    }\n\n    if (!materia.trim()) {\n      nuevos.materia = 'Ingresa la materia.';\n    } else if (materia.trim().length > 60) {\n      nuevos.materia = 'La materia no debe exceder 60 caracteres.';\n    }\n\n    if (descripcion.trim().length > 500) {\n      nuevos.descripcion = 'La descripción no debe exceder 500 caracteres.';\n    }\n\n    const esNuevaOReabierta = !tareaEditar || estado !== 'Finalizada';\n    if (esNuevaOReabierta && !tareaEditar && fecha.getTime() < Date.now() - 60000) {\n      nuevos.fecha = 'La fecha límite no puede estar en el pasado.';\n    }\n\n    setErrores(nuevos);\n    return Object.keys(nuevos).length === 0;\n  };\n\n  const guardar = async () => {\n    if (!validar()) return;\n    setGuardando(true);\n    const datos = {\n      titulo,\n      descripcion,\n      materia,\n      fechaLimite: fecha.toISOString(),\n      prioridad,\n      estado,\n    };\n    try {\n      if (tareaEditar) {\n        await actualizar(tareaEditar.id, datos);\n      } else {\n        await crear(datos);\n      }\n      navigation.goBack();\n    } catch (e) {\n      setGuardando(false);\n      Alert.alert('Error', e.message || 'No se pudo guardar la tarea.');\n    }\n  };\n\n  const confirmarEliminar = () => {\n    Alert.alert('Eliminar tarea', '¿Eliminar esta tarea? Esta acción no se puede deshacer.', [\n      { text: 'Cancelar', style: 'cancel' },\n      {\n        text: 'Eliminar',\n        style: 'destructive',\n        onPress: async () => {\n          try {\n            await eliminar(tareaEditar.id);\n            navigation.goBack();\n          } catch (e) {\n            Alert.alert('Error', e.message || 'No se pudo eliminar la tarea.');\n          }\n        },\n      },\n    ]);\n  };\n\n  return (\n    <KeyboardAvoidingView\n      style={styles.flex}\n      behavior={Platform.OS === 'ios' ? 'padding' : undefined}\n    >\n      <ScrollView contentContainerStyle={styles.scroll} keyboardShouldPersistTaps=\"handled\">\n        <FormInput\n          label=\"Título\"\n          placeholder=\"Ej. Entregar reporte de la práctica 5\"\n          value={titulo}\n          onChangeText={(t) => {\n            setTitulo(t);\n            limpiarError('titulo');\n          }}\n          error={errores.titulo}\n          autoCapitalize=\"sentences\"\n          maxLength={80}\n          returnKeyType=\"next\"\n          onSubmitEditing={() => materiaRef.current && materiaRef.current.focus()}\n          blurOnSubmit={false}\n        />\n\n        <FormInput\n          ref={materiaRef}\n          label=\"Materia\"\n          placeholder=\"Ej. Programación Funcional\"\n          value={materia}\n          onChangeText={(t) => {\n            setMateria(t);\n            limpiarError('materia');\n          }}\n          error={errores.materia}\n          autoCapitalize=\"words\"\n          maxLength={60}\n          returnKeyType=\"next\"\n          onSubmitEditing={() => descripcionRef.current && descripcionRef.current.focus()}\n          blurOnSubmit={false}\n        />\n\n        <FormInput\n          ref={descripcionRef}\n          label=\"Descripción (opcional)\"\n          placeholder=\"Detalles, requisitos o notas de la tarea\"\n          value={descripcion}\n          onChangeText={(t) => {\n            setDescripcion(t);\n            limpiarError('descripcion');\n          }}\n          error={errores.descripcion}\n          autoCapitalize=\"sentences\"\n          multiline\n          numberOfLines={4}\n          textAlignVertical=\"top\"\n          maxLength={500}\n          inputStyle={styles.multilinea}\n        />\n\n        <Text style={styles.label}>Fecha y hora límite</Text>\n        {Platform.OS === 'android' ? (\n          <Pressable\n            onPress={abrirSelectorAndroid}\n            style={[styles.selectorFecha, !!errores.fecha && styles.selectorError]}\n            accessibilityRole=\"button\"\n            accessibilityLabel=\"Elegir fecha y hora límite\"\n          >\n            <Text style={styles.selectorTexto}>{formatearFecha(fecha.toISOString())}</Text>\n            <Text style={styles.selectorHora}>{formatearHora(fecha.toISOString())}</Text>\n          </Pressable>\n        ) : (\n          <View style={[styles.selectorFechaIos, !!errores.fecha && styles.selectorError]}>\n            <DateTimePicker\n              value={fecha}\n              mode=\"datetime\"\n              display=\"compact\"\n              locale=\"es-MX\"\n              onChange={(evento, elegida) => {\n                if (elegida) {\n                  setFecha(elegida);\n                  limpiarError('fecha');\n                }\n              }}\n            />\n          </View>\n        )}\n        {!!errores.fecha && <Text style={styles.error}>{errores.fecha}</Text>}\n\n        <Text style={[styles.label, styles.separado]}>Prioridad</Text>\n        <View style={styles.fila}>\n          {PRIORIDADES.map((p) => {\n            const activo = prioridad === p;\n            const color = PRIORIDAD_COLORES[p];\n            return (\n              <Pressable\n                key={p}\n                onPress={() => setPrioridad(p)}\n                style={[\n                  styles.opcion,\n                  activo && { backgroundColor: color.bg, borderColor: color.fg },\n                ]}\n                accessibilityRole=\"button\"\n                accessibilityState={{ selected: activo }}\n              >\n                <Text style={[styles.opcionTexto, activo && { color: color.fg }]}>{p}</Text>\n              </Pressable>\n            );\n          })}\n        </View>\n\n        <Text style={[styles.label, styles.separado]}>Estado</Text>\n        <View style={styles.fila}>\n          {ESTADOS.map((e) => {\n            const activo = estado === e;\n            const color = ESTADO_COLORES[e];\n            return (\n              <Pressable\n                key={e}\n                onPress={() => setEstado(e)}\n                style={[\n                  styles.opcion,\n                  activo && { backgroundColor: color.bg, borderColor: color.fg },\n                ]}\n                accessibilityRole=\"button\"\n                accessibilityState={{ selected: activo }}\n              >\n                <Text style={[styles.opcionTexto, activo && { color: color.fg }]}>{e}</Text>\n              </Pressable>\n            );\n          })}\n        </View>\n\n        <Pressable\n          style={({ pressed }) => [\n            styles.botonGuardar,\n            pressed && styles.botonPresionado,\n            guardando && styles.botonDeshabilitado,\n          ]}\n          onPress={guardar}\n          disabled={guardando}\n          accessibilityRole=\"button\"\n        >\n          {guardando ? (\n            <ActivityIndicator color=\"#FFFFFF\" />\n          ) : (\n            <Text style={styles.botonGuardarTexto}>\n              {tareaEditar ? 'Guardar cambios' : 'Crear tarea'}\n            </Text>\n          )}\n        </Pressable>\n\n        {tareaEditar && (\n          <Pressable\n            style={styles.botonEliminar}\n            onPress={confirmarEliminar}\n            disabled={guardando}\n            accessibilityRole=\"button\"\n          >\n            <Text style={styles.botonEliminarTexto}>Eliminar tarea</Text>\n          </Pressable>\n        )}\n      </ScrollView>\n    </KeyboardAvoidingView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  flex: {\n    flex: 1,\n    backgroundColor: colors.background,\n  },\n  scroll: {\n    padding: spacing.lg,\n    paddingBottom: spacing.xl * 2,\n  },\n  label: {\n    fontSize: 14,\n    fontWeight: '600',\n    color: colors.text,\n    marginBottom: spacing.xs,\n  },\n  separado: {\n    marginTop: spacing.md,\n  },\n  multilinea: {\n    height: 100,\n    paddingTop: 12,\n  },\n  selectorFecha: {\n    flexDirection: 'row',\n    justifyContent: 'space-between',\n    alignItems: 'center',\n    backgroundColor: colors.surface,\n    borderWidth: 1,\n    borderColor: colors.border,\n    borderRadius: 10,\n    height: 48,\n    paddingHorizontal: 14,\n  },\n  selectorFechaIos: {\n    alignItems: 'flex-start',\n    backgroundColor: colors.surface,\n    borderWidth: 1,\n    borderColor: colors.border,\n    borderRadius: 10,\n    paddingVertical: spacing.sm,\n    paddingHorizontal: 10,\n  },\n  selectorError: {\n    borderColor: colors.error,\n  },\n  selectorTexto: {\n    fontSize: 16,\n    color: colors.text,\n  },\n  selectorHora: {\n    fontSize: 16,\n    fontWeight: '700',\n    color: colors.primary,\n  },\n  error: {\n    color: colors.error,\n    fontSize: 12,\n    marginTop: spacing.xs,\n  },\n  fila: {\n    flexDirection: 'row',\n    flexWrap: 'wrap',\n  },\n  opcion: {\n    paddingHorizontal: 14,\n    paddingVertical: 9,\n    borderRadius: 20,\n    backgroundColor: colors.surface,\n    borderWidth: 1.5,\n    borderColor: colors.border,\n    marginRight: spacing.sm,\n    marginBottom: spacing.sm,\n  },\n  opcionTexto: {\n    fontSize: 14,\n    fontWeight: '600',\n    color: colors.muted,\n  },\n  botonGuardar: {\n    backgroundColor: colors.primary,\n    borderRadius: 10,\n    height: 50,\n    alignItems: 'center',\n    justifyContent: 'center',\n    marginTop: spacing.lg,\n  },\n  botonPresionado: {\n    backgroundColor: colors.primaryDark,\n  },\n  botonDeshabilitado: {\n    opacity: 0.7,\n  },\n  botonGuardarTexto: {\n    color: '#FFFFFF',\n    fontSize: 16,\n    fontWeight: '700',\n  },\n  botonEliminar: {\n    height: 50,\n    alignItems: 'center',\n    justifyContent: 'center',\n    borderRadius: 10,\n    borderWidth: 1.5,\n    borderColor: colors.error,\n    marginTop: spacing.md,\n  },\n  botonEliminarTexto: {\n    color: colors.error,\n    fontSize: 16,\n    fontWeight: '700',\n  },\n});\n",
  "scripts/actualizar.js": "const { execSync } = require('child_process');\n\nconst mensaje = process.argv.slice(2).join(' ').trim() || 'Actualización de TecSolv';\nconst run = (cmd) => execSync(cmd, { stdio: 'inherit' });\n\nrun('git add -A');\ntry {\n  run(`git commit -m ${JSON.stringify(mensaje)}`);\n} catch (e) {\n  console.log('No hay cambios para confirmar.');\n  process.exit(0);\n}\nrun('git push');\nconsole.log('\\nListo. GitHub compilará el nuevo APK y los usuarios recibirán el aviso de actualización.');\n",
  "scripts/subir-a-github.js": "const { execSync } = require('child_process');\nconst fs = require('fs');\n\nconst url = process.argv[2];\nif (!url) {\n  console.error('Uso: node scripts/subir-a-github.js https://github.com/USUARIO/tecsolv.git');\n  process.exit(1);\n}\n\nconst run = (cmd) => execSync(cmd, { stdio: 'inherit' });\n\nif (!fs.existsSync('.git')) {\n  run('git init -b main');\n}\nrun('git add -A');\ntry {\n  run('git commit -m \"Versión inicial de TecSolv\"');\n} catch (e) {\n  console.log('Nada nuevo que confirmar.');\n}\ntry {\n  execSync('git remote remove origin', { stdio: 'ignore' });\n} catch (e) {}\nrun(`git remote add origin ${url}`);\nrun('git push -u origin main');\nconsole.log('\\nListo. En GitHub ve a Actions: se compilará el APK y aparecerá en Releases.');\n",
  "services/authService.js": "import AsyncStorage from '@react-native-async-storage/async-storage';\nimport * as Crypto from 'expo-crypto';\n\nconst USERS_KEY = '@tecsolv_users';\nconst SESSION_KEY = '@tecsolv_session';\n\nconst normalizarEmail = (email) => String(email || '').trim().toLowerCase();\n\nconst generarSalt = async () => {\n  const bytes = await Crypto.getRandomBytesAsync(16);\n  return Array.from(bytes)\n    .map((b) => b.toString(16).padStart(2, '0'))\n    .join('');\n};\n\nconst hashPassword = (password, salt) =>\n  Crypto.digestStringAsync(Crypto.CryptoDigestAlgorithm.SHA256, salt + password);\n\nconst leerUsuarios = async () => {\n  const raw = await AsyncStorage.getItem(USERS_KEY);\n  if (!raw) return [];\n  try {\n    const data = JSON.parse(raw);\n    return Array.isArray(data) ? data : [];\n  } catch (e) {\n    return [];\n  }\n};\n\nconst guardarSesion = async (usuario) => {\n  const sesion = {\n    id: usuario.id,\n    nombre: usuario.nombre,\n    email: usuario.email,\n    iniciadaEn: new Date().toISOString(),\n  };\n  await AsyncStorage.setItem(SESSION_KEY, JSON.stringify(sesion));\n  return sesion;\n};\n\nexport async function registrarUsuario({ nombre, email, password }) {\n  const emailNorm = normalizarEmail(email);\n  const usuarios = await leerUsuarios();\n\n  if (usuarios.some((u) => u.email === emailNorm)) {\n    throw new Error('Ya existe una cuenta registrada con ese correo.');\n  }\n\n  const salt = await generarSalt();\n  const passwordHash = await hashPassword(password, salt);\n  const nuevo = {\n    id: `u_${Date.now()}_${salt.slice(0, 6)}`,\n    nombre: String(nombre).trim(),\n    email: emailNorm,\n    salt,\n    passwordHash,\n    creadoEn: new Date().toISOString(),\n  };\n\n  await AsyncStorage.setItem(USERS_KEY, JSON.stringify([...usuarios, nuevo]));\n  return guardarSesion(nuevo);\n}\n\nexport async function iniciarSesion({ email, password }) {\n  const emailNorm = normalizarEmail(email);\n  const usuarios = await leerUsuarios();\n  const usuario = usuarios.find((u) => u.email === emailNorm);\n\n  if (!usuario) {\n    throw new Error('Correo o contraseña incorrectos.');\n  }\n\n  const hash = await hashPassword(password, usuario.salt);\n  if (hash !== usuario.passwordHash) {\n    throw new Error('Correo o contraseña incorrectos.');\n  }\n\n  return guardarSesion(usuario);\n}\n\nexport async function obtenerSesion() {\n  const raw = await AsyncStorage.getItem(SESSION_KEY);\n  if (!raw) return null;\n  try {\n    return JSON.parse(raw);\n  } catch (e) {\n    await AsyncStorage.removeItem(SESSION_KEY);\n    return null;\n  }\n}\n\nexport async function cerrarSesion() {\n  await AsyncStorage.removeItem(SESSION_KEY);\n}\n",
  "services/taskService.js": "import AsyncStorage from '@react-native-async-storage/async-storage';\n\nconst claveTareas = (userId) => `@tecsolv_tasks_${userId}`;\n\nconst generarId = () => `t_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;\n\nexport async function obtenerTareas(userId) {\n  const raw = await AsyncStorage.getItem(claveTareas(userId));\n  if (!raw) return [];\n  try {\n    const data = JSON.parse(raw);\n    return Array.isArray(data) ? data : [];\n  } catch (e) {\n    return [];\n  }\n}\n\nconst guardarTareas = (userId, lista) =>\n  AsyncStorage.setItem(claveTareas(userId), JSON.stringify(lista));\n\nexport async function crearTarea(userId, datos) {\n  const lista = await obtenerTareas(userId);\n  const ahora = new Date().toISOString();\n  const tarea = {\n    id: generarId(),\n    titulo: String(datos.titulo).trim(),\n    descripcion: String(datos.descripcion || '').trim(),\n    materia: String(datos.materia).trim(),\n    fechaLimite: datos.fechaLimite,\n    prioridad: datos.prioridad,\n    estado: datos.estado || 'Pendiente',\n    creadaEn: ahora,\n    actualizadaEn: ahora,\n  };\n  const nueva = [...lista, tarea];\n  await guardarTareas(userId, nueva);\n  return { lista: nueva, tarea };\n}\n\nexport async function actualizarTarea(userId, id, cambios) {\n  const lista = await obtenerTareas(userId);\n  const indice = lista.findIndex((t) => t.id === id);\n  if (indice === -1) {\n    throw new Error('La tarea ya no existe.');\n  }\n  const limpios = { ...cambios };\n  if (typeof limpios.titulo === 'string') limpios.titulo = limpios.titulo.trim();\n  if (typeof limpios.descripcion === 'string') limpios.descripcion = limpios.descripcion.trim();\n  if (typeof limpios.materia === 'string') limpios.materia = limpios.materia.trim();\n\n  const tarea = {\n    ...lista[indice],\n    ...limpios,\n    id: lista[indice].id,\n    creadaEn: lista[indice].creadaEn,\n    actualizadaEn: new Date().toISOString(),\n  };\n  const nueva = [...lista];\n  nueva[indice] = tarea;\n  await guardarTareas(userId, nueva);\n  return { lista: nueva, tarea };\n}\n\nexport async function eliminarTarea(userId, id) {\n  const lista = await obtenerTareas(userId);\n  const nueva = lista.filter((t) => t.id !== id);\n  await guardarTareas(userId, nueva);\n  return nueva;\n}\n",
  "services/updateService.js": "import Constants from 'expo-constants';\n\nexport async function buscarActualizacion() {\n  const extra = (Constants.expoConfig && Constants.expoConfig.extra) || {};\n  const repo = extra.githubRepo;\n  const actual = Number(extra.buildNumber) || 0;\n\n  if (!repo || !actual) return null;\n\n  const respuesta = await fetch(`https://api.github.com/repos/${repo}/releases/latest`, {\n    headers: { Accept: 'application/vnd.github+json' },\n  });\n  if (!respuesta.ok) return null;\n\n  const datos = await respuesta.json();\n  const coincidencia = /build-(\\d+)/.exec(datos.tag_name || '');\n  if (!coincidencia) return null;\n\n  const ultima = Number(coincidencia[1]);\n  if (ultima <= actual) return null;\n\n  const apk = (datos.assets || []).find((a) => /\\.apk$/i.test(a.name));\n  return {\n    build: ultima,\n    nombre: datos.name || `Build ${ultima}`,\n    url: apk ? apk.browser_download_url : datos.html_url,\n  };\n}\n",
  "utils/taskUtils.js": "export const ESTADOS = ['Pendiente', 'En Progreso', 'Finalizada'];\nexport const PRIORIDADES = ['Alta', 'Media', 'Baja'];\n\nexport const PRIORIDAD_COLORES = {\n  Alta: { fg: '#B3261E', bg: '#FDECEA' },\n  Media: { fg: '#B26A00', bg: '#FFF4E0' },\n  Baja: { fg: '#1E8E3E', bg: '#E6F4EA' },\n};\n\nexport const ESTADO_COLORES = {\n  Pendiente: { fg: '#5B6475', bg: '#ECEEF3' },\n  'En Progreso': { fg: '#1E4FD8', bg: '#E4ECFD' },\n  Finalizada: { fg: '#1E8E3E', bg: '#E6F4EA' },\n};\n\nconst PESO_PRIORIDAD = { Alta: 0, Media: 1, Baja: 2 };\nconst MESES = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];\nconst DIAS = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];\n\nconst pad = (n) => String(n).padStart(2, '0');\n\nexport const inicioDelDia = (fecha) =>\n  new Date(fecha.getFullYear(), fecha.getMonth(), fecha.getDate());\n\nexport function formatearFecha(iso) {\n  const d = new Date(iso);\n  return `${DIAS[d.getDay()]} ${d.getDate()} ${MESES[d.getMonth()]} ${d.getFullYear()}`;\n}\n\nexport function formatearHora(iso) {\n  const d = new Date(iso);\n  return `${pad(d.getHours())}:${pad(d.getMinutes())}`;\n}\n\nexport function formatearFechaHora(iso) {\n  return `${formatearFecha(iso)}, ${formatearHora(iso)}`;\n}\n\nexport function normalizarTexto(texto) {\n  return String(texto || '')\n    .toLowerCase()\n    .normalize('NFD')\n    .replace(/[\\u0300-\\u036f]/g, '')\n    .trim();\n}\n\nexport function estaVencida(tarea) {\n  return tarea.estado !== 'Finalizada' && new Date(tarea.fechaLimite).getTime() < Date.now();\n}\n\nexport function contarPorEstado(tareas) {\n  const conteo = { Todas: tareas.length, Pendiente: 0, 'En Progreso': 0, Finalizada: 0 };\n  tareas.forEach((t) => {\n    if (conteo[t.estado] !== undefined) conteo[t.estado] += 1;\n  });\n  return conteo;\n}\n\nexport function filtrarTareas(tareas, { estado = 'Todas', busqueda = '' } = {}) {\n  const q = normalizarTexto(busqueda);\n  return tareas.filter((t) => {\n    if (estado !== 'Todas' && t.estado !== estado) return false;\n    if (!q) return true;\n    const texto = normalizarTexto(`${t.titulo} ${t.materia} ${t.descripcion}`);\n    return texto.includes(q);\n  });\n}\n\nconst ordenarPorFecha = (a, b) => {\n  const diff = new Date(a.fechaLimite).getTime() - new Date(b.fechaLimite).getTime();\n  if (diff !== 0) return diff;\n  return PESO_PRIORIDAD[a.prioridad] - PESO_PRIORIDAD[b.prioridad];\n};\n\nexport function agruparTareas(tareas) {\n  const ahora = new Date();\n  const hoy = inicioDelDia(ahora);\n  const grupos = {\n    Vencidas: [],\n    Hoy: [],\n    'Mañana': [],\n    'Esta semana': [],\n    'Más adelante': [],\n    Finalizadas: [],\n  };\n\n  tareas.forEach((t) => {\n    if (t.estado === 'Finalizada') {\n      grupos.Finalizadas.push(t);\n      return;\n    }\n    const fecha = new Date(t.fechaLimite);\n    if (fecha.getTime() < ahora.getTime()) {\n      grupos.Vencidas.push(t);\n      return;\n    }\n    const dias = Math.round((inicioDelDia(fecha).getTime() - hoy.getTime()) / 86400000);\n    if (dias <= 0) grupos.Hoy.push(t);\n    else if (dias === 1) grupos['Mañana'].push(t);\n    else if (dias <= 7) grupos['Esta semana'].push(t);\n    else grupos['Más adelante'].push(t);\n  });\n\n  const colores = {\n    Vencidas: '#B3261E',\n    Hoy: '#1E4FD8',\n    'Mañana': '#7B3FE4',\n    'Esta semana': '#B26A00',\n    'Más adelante': '#5B6475',\n    Finalizadas: '#1E8E3E',\n  };\n\n  return Object.keys(grupos)\n    .filter((titulo) => grupos[titulo].length > 0)\n    .map((titulo) => ({\n      title: titulo,\n      color: colores[titulo],\n      data:\n        titulo === 'Finalizadas'\n          ? grupos[titulo].sort((a, b) => ordenarPorFecha(b, a))\n          : grupos[titulo].sort(ordenarPorFecha),\n    }));\n}\n"
};

const destino = path.resolve(process.argv[2] || 'tecsolv');

Object.keys(archivos).forEach((rel) => {
  const ruta = path.join(destino, rel);
  fs.mkdirSync(path.dirname(ruta), { recursive: true });
  fs.writeFileSync(ruta, archivos[rel], 'utf8');
  console.log('creado: ' + rel);
});

